def semver_sort(versions):
    def parse(v):
        # strip build metadata
        main_part = v.split('+', 1)[0]
        if '-' in main_part:
            core, prerelease = main_part.split('-', 1)
        else:
            core, prerelease = main_part, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if prerelease is None:
            has_pre = 1  # no prerelease sorts after
            ids_key = []
        else:
            has_pre = 0  # has prerelease sorts before
            ids = prerelease.split('.')
            ids_key = []
            for ident in ids:
                if ident.isdigit():
                    ids_key.append((0, int(ident)))
                else:
                    ids_key.append((1, ident))

        return (major, minor, patch, has_pre, ids_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for _, v in sorted(indexed, key=lambda pair: (parse(pair[1]),))]

